INSERT INTO `disaster_requests` VALUES (1,'REQ-2026-001',12,'Purok Riverside 1 & 2','Flood','Critical','Immediate',350,1540,220,0,4,0,'Requesting urgent dispatch of 350 Family Food Packs, 200 Hygiene Kits, 2 Inflatable Rescue Boats with operators, and 60 Life Vests due to rising Mandulog River overflow.','Mandulog river level reached 4.2 meters (Red Warning Stage). Water has entered low-lying residential clusters in Purok Riverside 1 and 2. 220 families already evacuated to Hinaplanon NHS Gym.',NULL,'Recommendation Ready',2,'2026-10-03 18:46:32','2026-10-03 22:46:32',NULL),(2,'REQ-2026-002',38,'Purok 1 Baybay','Storm Surge','High','High',180,790,95,0,1,0,'Requesting 180 Family Food Packs, 100 Hygiene Kits, 50 Modular Tents, and First Aid replenishment for coastal evacuees.','High tide coupled with localized squall caused 1.8-meter sea swells battering coastal households along Purok 1 Baybay.',NULL,'Approved',3,'2026-10-02 22:46:32','2026-10-03 22:46:32',NULL),(3,'REQ-2026-003',12,'Purok San Miguel','Flash Flood','Moderate','Medium',90,395,25,0,0,0,'Pre-emptive prepositioning of 90 Food Packs and 2 Portable Water Pumps in case creek drainage overflows.','Heavy continuous rain recorded over the hinterlands. Creek drainage in Purok San Miguel experiencing sluggish runoff.',NULL,'Submitted',2,'2026-10-03 20:46:32','2026-10-03 22:46:32',NULL);
/*!40000 ALTER TABLE `disaster_requests` ENABLE KEYS */;
