INSERT INTO `preparedness_activities` VALUES (1,'4th Quarter Nationwide Simultaneous Earthquake Drill (NSED)','Disaster Drill',12,'Hinaplanon Central Plaza & Elementary Grounds','2026-10-15 09:00:00','2026-10-15 11:30:00','Team Alpha - Engr. Castillo & Kurt Morales',300,0,'Community-wide earthquake evacuation simulation focusing on \"Duck, Cover, and Hold\" protocols, secondary fire response, and designated safe rally zone management.','Cancelled',NULL,1,'2026-10-03 22:46:32'),(2,'Barangay Emergency Responders Water Rescue Refresher','First Aid / Rescuer Training',12,'Mandulog Riverbank Drill Station','2026-10-22 08:00:00','2026-10-22 16:00:00','ICDRRMO Water Search & Rescue Unit',45,0,'Hands-on practical training covering rope throwing, capsize recovery, outboard motor handling, and hypothermia first aid for coastal and riverine responders.','Cancelled',NULL,1,'2026-10-03 22:46:32'),(3,'Community Flood Preparedness & Family Go-Bag Workshop','IEC Campaign',12,'Purok San Miguel Covered Court','2026-09-20 13:30:00','2026-09-20 16:30:00','Nurse Sarah Jane & Brgy Council',120,114,'Educational seminar demonstrating 72-hour family emergency kit preparation, early warning color alerts, and pre-emptive evacuation procedures.','Completed','High resident participation. 114 households certified on household evacuation readiness checklist.',2,'2026-10-03 22:46:32'),(4,'Basic Incident Command System (BICS) for Barangay Officials','Contingency Planning',38,'Tomas Cabili Barangay Hall Session Hall','2026-10-28 08:30:00','2026-10-29 17:00:00','ICDRRMO Training Division',30,0,'Institutional capacity building for Barangay Disaster Risk Reduction and Management Committee (BDRRMC) core members on unified command and logistics mobilization.','Scheduled',NULL,1,'2026-10-03 22:46:32'),(5,'asdqwe','Community Seminar',12,'asdasd','2026-10-07 12:00:00','2026-10-07 15:00:00','asdasdasd',60,1,'asdasd','Cancelled',NULL,2,'2026-10-06 12:14:54'),(6,'ffff','Disaster Drill',12,'fff','2026-10-07 12:00:00','2026-10-07 15:00:00','fff',60,0,'ffff','Cancelled',NULL,2,'2026-10-06 12:35:05'),(7,'zzz','Disaster Drill',12,'zzzz','2026-10-07 12:00:00','2026-10-07 15:00:00','zzz',60,0,'zzzz','Cancelled',NULL,2,'2026-10-06 12:38:07'),(8,'eee','Disaster Drill',12,'eeee','2026-10-07 13:00:00','2026-10-07 16:00:00','eee',60,0,'eeee','Cancelled',NULL,2,'2026-10-06 13:22:05'),(9,'asasas','Disaster Drill',12,'asasas','2026-10-07 13:00:00','2026-10-07 16:00:00','asas',60,0,'asasas','Cancelled',NULL,2,'2026-10-06 13:31:57'),(10,'yyy','Disaster Drill',12,'yyy','2026-10-07 14:00:00','2026-10-07 17:00:00','yyy',60,0,'yyy','Scheduled',NULL,2,'2026-10-06 14:27:01'),(11,'sample','Disaster Drill',12,'sample1','2026-10-07 14:00:00','2026-10-07 17:00:00','sample1',60,0,'sample1','Scheduled',NULL,2,'2026-10-06 14:35:00');
