INSERT INTO `resources` VALUES (1,'RES-FOOD-001','Standard Family Food Pack (3-day ration)','Relief Goods','active','DSWD National Disaster Logistics Standard 3-Day Family Food Pack. Contains 6kg NFA Well-Milled Rice, 4 cans 155g Sardines in Tomato Sauce, 4 cans 150g Corned Beef, 6 sachets 3-in-1 Coffee, and 5 packs Instant Mami Noodles.','packs',2400,1850,500,50,400,'Central ICDRRMO Depot A (Aisle 1-A)','BATCH-FFP-2026-08','DSWD Field Office X / National Resource Operations Center (NROC)','2026-02-10','2026-11-30',1,'DSWD / NFA Standard','7.8 kg',550.00,'Good',NULL,'2026-10-05 18:24:28','2026-10-03 22:46:32'),(2,'RES-FOOD-002','Ready-to-Eat Emergency Meals (RTE Retort Pouch)','Relief Goods','active','Military-spec shelf-stable retort pouch meals requiring zero heating or water reconstitution. Flavors: Chicken Adobo with Rice and Beef Caldereta with Rice. Hermetically sealed vacuum packs.','packs',1200,950,220,30,250,'Central ICDRRMO Depot A (Aisle 1-B)','LOT-RTE-2026-X14','Office of Civil Defense (OCD) Region X Quick Response Reserve','2026-01-20','2027-01-20',1,'San Miguel Purefoods RTE','0.45 kg',145.00,'New',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(3,'RES-WATER-001','Bottled Mineral Drinking Water (6L Dispenser Bottle)','Relief Goods','active','6-Liter food-grade PET containers of purified drinking water with sturdy carry handle and tamper-evident cap seal. Tested and certified by DOH FDA.','bottles',1800,1340,420,40,300,'Depot B - Pallet Bay 4 (Water Reserve)','LOT-NS-6L-202604','Iligan City LGU Calamity Procurement Fund','2026-03-01','2028-03-01',1,'Nature\'s Spring Mineral Water','6.15 kg',85.00,'Good',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(4,'RES-HYG-001','Family Hygiene & Sanitation Kit','Shelter & Sanitation','active','Complete family hygiene package in durable waterproof plastic tote bag: 5 toothbrushes, 2 tubes 150ml fluoride toothpaste, 4 bath soaps, 1kg laundry detergent bar, 2 packs 10s sanitary napkins, 250ml 70% isopropyl alcohol, 2 plastic combs, and 3 quick-dry micro-fiber hand towels.','kits',950,680,250,20,150,'Central ICDRRMO Depot B (Aisle 2-A)','HYG-UNICEF-PH-2026','UNICEF Philippines / DSWD Field Office X','2026-01-15','2028-06-30',0,'P&G / Unilever DSWD Standard','2.4 kg',620.00,'New',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(5,'RES-MED-001','Disaster First Aid Response Kit (Heavy Duty Bag)','Medical Supplies','active','Tactical water-resistant Cordura medical bag containing sterile trauma dressings, elastic crepe bandages, tourniquet, Povidone Iodine 10%, sterile gauze sponges, surgical tape, burn dressing pads, trauma shears, examination gloves, CPR pocket mask, and thermal emergency blankets.','kits',320,240,75,5,60,'ICDRRMO Medical Bay (Cabinet Alpha)','FAK-IND-2026-09A','Philippine Red Cross - Iligan City Chapter','2026-02-05','2027-10-31',1,'Indoplas Medical Supplies','1.8 kg',1850.00,'Good',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(6,'RES-MED-002','Essential Medicine Dispensing Pack (Box of 500 doses)','Medical Supplies','active','Clinical evacuation dispensary pack containing: Paracetamol 500mg (150 tabs), Oral Rehydration Salts sachets (100 pkts), Amoxicillin 500mg (100 caps), Cetirizine 10mg (50 tabs), Mefenamic Acid 500mg (50 tabs), Loperamide 2mg (50 caps). Includes dispensing envelopes.','boxes',450,310,130,10,80,'ICDRRMO Medical Bay (Climate-Controlled Cabinet B)','UNILAB-MED-2026-901','Department of Health (DOH) Center for Health Development Region X','2026-03-15','2026-10-25',1,'Unilab United Laboratories','1.2 kg',3200.00,'Good',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(7,'RES-RESC-001','Inflatable Rescue Boat with 25HP Outboard Motor','Rescue Equipment','active','Heavy-duty 4.2-meter rigid inflatable rubber boat (Hypalon 1100 Denier), 6-passenger capacity, reinforced aluminum floorboards, 25HP Yamaha 2-stroke outboard engine, 24L remote fuel tank, 4 emergency paddles, tow bridles, and repair kit.','units',12,7,5,0,3,'Water Rescue Logistics Bay (Trailer Dock 1-4)','ENG-YM-25HP-2025B','National Disaster Risk Reduction & Management Council (NDRRMC)','2025-08-20',NULL,0,'Yamaha Marine / Zodiac Milpro','95.0 kg',285000.00,'Good',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(8,'RES-RESC-002','Standard Personal Flotation Device (SOLAS Type-III PFD)','Rescue Equipment','active','Coast Guard & SOLAS certified high-buoyancy life vest with high-visibility international orange ripstop nylon shell, PE foam core, 3 heavy-duty adjustable buckles, SOLAS-grade retroreflective tape, and pea-less marine emergency whistle.','units',450,310,135,5,80,'Water Rescue Logistics Bay (Rack 2)','PFD-STR-2025-450','Philippine Coast Guard Auxiliary / ICDRRMO Logistics','2025-11-12',NULL,0,'Stearns Flotation Marine','0.85 kg',1450.00,'Good',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(9,'RES-RESC-003','Heavy Rescue Chainsaw (Gasoline 24-inch Bar)','Rescue Equipment','active','72.2cc two-stroke high-torque gasoline rescue chainsaw with 24-inch carbide-tipped rescue chain for swift clearing of fallen trees, utility poles, and collapsed wooden roofing. Includes spark plug wrench, 2-cycle oil mix, and chain guard.','units',16,11,4,1,4,'Search & Rescue Shed (Locker Bay 3)','SN-STIHL-MS382-77','City Government of Iligan Capital Outlay','2025-06-18',NULL,0,'Stihl MS 382 Professional','6.6 kg',42000.00,'Good',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(10,'RES-SHEL-001','Family Evacuation Modular Privacy Tent (3m x 3m)','Shelter & Sanitation','active','Standard NDRRMC/DSWD emergency pop-up modular privacy cubicle tent (3m x 3m x 1.8m height). Heavy-duty flame-retardant Oxford 210D polyester, zip-up front mesh door, 2 side ventilation windows, integrated ground sheet, and carry bag.','units',600,420,170,10,100,'Depot C - Shelter Storage (Sector 1)','TENT-DSWD-MOD-2026','DSWD Disaster Response Management Bureau (DRMB)','2026-01-28',NULL,0,'Coleman / DSWD Standard','4.8 kg',2800.00,'New',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(11,'RES-EMRG-001','Heavy Duty Quiet Inverter Gasoline Generator (7.5kVA)','Emergency Supplies','active','7.5kVA (6000W rated) portable digital inverter generator, electric push start with manual recoil backup, 25-liter long-run fuel tank (9 hours runtime at 50% load), twin 220V AC GFCI outlets, 12V DC charger port, digital hour meter, and heavy-duty transport wheels.','units',18,9,8,1,4,'Equipment Depot C (Power Equipment Bay)','GEN-HND-EU7000-09','Office of Civil Defense (OCD) Region X / Calamity Grant','2025-09-14',NULL,0,'Honda Power Equipment EU70is','62.0 kg',88000.00,'Good',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(12,'RES-EMRG-002','High-Output Rechargeable LED Searchlight & Area Floodlight','Emergency Supplies','active','5000-Lumen tactical spotlight and 360-degree scene floodlight. IP67 dust/waterproof rating, integrated 20,000mAh lithium-ion power bank with USB-C fast charging, telescopic tripod mast up to 1.8 meters, and magnetic mounting base.','units',80,52,26,2,20,'Equipment Depot C (Locker C-4)','LOT-LED-5000L-2026','Iligan City CDRRMC General Fund','2026-02-18',NULL,0,'Milwaukee Rover Scene Light','3.2 kg',9500.00,'New',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(13,'RES-FOOD-003','High-Energy Disaster Relief Biscuits (HEB)','Relief Goods','active','Nutrient-dense fortified wheat biscuits fortified with 15 essential vitamins and minerals for acute disaster feeding when cooking facilities are inaccessible. 500g vacuum-sealed foil pack (2,100 kcal).','packs',1500,1200,300,0,200,'Central ICDRRMO Depot A (Aisle 2-B)','LOT-WFP-HEB-2026-03','United Nations World Food Programme (UN-WFP)','2026-03-05','2028-03-05',1,'WFP Fortified Relief Food','0.5 kg',65.00,'New',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(14,'RES-EMRG-003','High-Capacity Submersible De-Watering Trash Pump (3-inch)','Emergency Supplies','active','Heavy-duty 7.0HP gasoline engine water trash pump, 3-inch suction/discharge ports, 1300 L/min maximum discharge capacity, pass solids up to 25mm diameter. Includes 20m high-pressure layflat hose and strainer.','units',14,8,6,0,3,'Equipment Depot C (Pump Staging Bay)','PUMP-KOSH-3IN-2025','DPWH District Engineering Office / ICDRRMO Prepositioned','2025-10-10',NULL,0,'Koshin Trash Pump (Japan)','48.0 kg',38500.00,'Good',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(15,'RES-MED-003','Sterile Intravenous Fluid & Infusion Set (0.9% NaCl 1000mL)','Medical Supplies','active','Sterile normal saline 0.9% Sodium Chloride 1000mL in non-PVC bag with sterile macro-drip IV infusion administration set, 18G & 20G safety IV catheters, tourniquet, and alcohol prep pads for emergency dehydration and hemorrhagic shock treatment.','sets',400,280,110,10,60,'ICDRRMO Medical Bay (Sterile IV Locker)','LOT-EUROMED-IV-7821','City Health Office (CHO) Emergency Pharmacy','2026-02-14','2027-02-14',1,'Euro-Med Laboratories','1.1 kg',240.00,'Good',NULL,'2026-10-03 22:46:32','2026-10-03 22:46:32'),(16,'TEST-BRG1-1233','Emergency Generator 5kVA','Rescue Equipment','active','Test Generator','sets',3,3,0,0,1,'Brgy 1 Stockroom',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'New',1,'2026-10-05 18:23:05','2026-10-05 18:23:05');
