INSERT INTO `sms_logs` VALUES (1,'09701965951','angel nadayag','BARANGAY DISASTER ADVISORY\nHi angel nadayag!\nA new community event has been scheduled in your barangay:\nEvent: asdqwe\nVenue: asdasd\nStart: Oct 07, 2026 12:00 PM\nEnd: Oct 07, 2026 03:00 PM\nLead Facilitator: asdasdasd\nDetails: asdasd\nPlease be guided accordingly. Thank you!','sent',NULL,'event_created',5,'2026-10-06 12:22:23'),(2,'09701965951','angel nadayag','BARANGAY DISASTER ADVISORY\nHi angel nadayag!\nA new event has been scheduled in your barangay:\nEvent: ffff\nVenue: fff\nStart: Oct 07, 2026 12:00 PM\nEnd: Oct 07, 2026 03:00 PM\nLead Facilitator: fff\nDetails: ffff\nPlease be guided accordingly. Thank you!','sent',NULL,'event_created',6,'2026-10-06 12:35:05'),(3,'09701965951','angel nadayag','BARANGAY DISASTER ADVISORY\nHi angel nadayag!\nA new event has been scheduled in your barangay:\nEvent: zzz\nVenue: zzzz\nStart: Oct 07, 2026 12:00 PM\nEnd: Oct 07, 2026 03:00 PM\nLead Facilitator: zzz\nDetails: zzzz\nPlease be guided accordingly. Thank you!','sent',NULL,'event_created',7,'2026-10-06 12:38:07'),(4,'+639701965951','angel nadayag','BARANGAY DISASTER ADVISORY\nHi angel nadayag!\nA new community event has been scheduled in your barangay:\nEvent: asdqwe\nVenue: asdasd\nStart: Oct 07, 2026 12:00 PM\nEnd: Oct 07, 2026 03:00 PM\nLead Facilitator: asdasdasd\nDetails: asdasd\nPlease be guided accordingly. Thank you!','simulated (No API Key)','Notice: SMS Gateway API Key is not yet configured in backend/config/config.php (SMS_API_KEY). Message was logged into database successfully.','event_created',5,'2026-10-06 12:43:38'),(5,'+639701965951','angel nadayag','BARANGAY DISASTER ADVISORY\nHi angel nadayag!\nA new event has been scheduled in your barangay:\nEvent: eee\nVenue: eeee\nStart: Oct 07, 2026 01:00 PM\nEnd: Oct 07, 2026 04:00 PM\nLead Facilitator: eee\nDetails: eeee\nPlease be guided accordingly. Thank you!','failed','Your account has not yet been approved for sending messages. Please either top-up your account or wait for your account to be approved. If your account has not been approved within 2 business days, please email support@semaphore.co','event_created',8,'2026-10-06 13:22:06'),(6,'+639701965951','angel nadayag','BARANGAY DISASTER ADVISORY\nHi angel nadayag!\nA new event has been scheduled in your barangay:\nEvent: asasas\nVenue: asasas\nStart: Oct 07, 2026 01:00 PM\nEnd: Oct 07, 2026 04:00 PM\nLead Facilitator: asas\nDetails: asasas\nPlease be guided accordingly. Thank you!','failed','Your account has not yet been approved for sending messages. Please either top-up your account or wait for your account to be approved. If your account has not been approved within 2 business days, please email support@semaphore.co','event_created',9,'2026-10-06 13:31:57'),(7,'+639701965951','angel nadayag','Test SMS advisory from Barangay Disaster System','simulated (TextBee Key needed)','TextBee Free Gateway selected. Please register at https://app.textbee.dev, install the TextBee Android app, and paste your TEXTBEE_API_KEY into .env.','test',1,'2026-10-06 13:48:08'),(8,'+639701965951','angel nadayag','Test SMS advisory from Barangay Disaster System','failed','{\"success\":false,\"error\":\"No enabled device found. Enable a device or pass a deviceId.\"}','test',1,'2026-10-06 13:57:05'),(9,'+639701965951','angel nadayag','Test SMS advisory from Barangay Disaster System','sent','{\"data\":{\"success\":true,\"message\":\"SMS added to queue for processing\",\"smsBatchId\":\"6ac493f82597187c9cc0f683\",\"recipientCount\":1}}','test',1,'2026-10-06 14:23:52'),(10,'+639701965951','angel nadayag','BARANGAY DISASTER ADVISORY\nHi angel nadayag!\nA new event has been scheduled in your barangay:\nEvent: yyy\nVenue: yyy\nStart: Oct 07, 2026 02:00 PM\nEnd: Oct 07, 2026 05:00 PM\nLead Facilitator: yyy\nDetails: yyy\nPlease be guided accordingly. Thank you!','sent','{\"data\":{\"success\":true,\"message\":\"SMS added to queue for processing\",\"smsBatchId\":\"6ac494b72597187c9cc19261\",\"recipientCount\":1}}','event_created',10,'2026-10-06 14:27:04'),(11,'+639701965951','angel nadayag','BARANGAY DISASTER RISK REDUCTION AND MANAGEMENT COMMITTEE (Hinaplanon)\nHi angel nadayag!\nYou are registered for: Community Earthquake & Evacuation Drill\nVenue: Barangay Covered Court\nStart: Oct 07, 2026 09:00 AM\nEnd: Oct 07, 2026 12:00 PM\nLead Facilitator: Barangay Disaster Team\nDetails: Community disaster preparedness and safety orientation.\nThank you for participating!','sent','{\"data\":{\"success\":true,\"message\":\"SMS added to queue for processing\",\"smsBatchId\":\"6ac4963c2597187c9cc2cd20\",\"recipientCount\":1}}','event',1,'2026-10-06 14:33:32'),(12,'+639701965951','angel nadayag','BARANGAY DISASTER RISK REDUCTION AND MANAGEMENT COMMITTEE (Hinaplanon)\nHi angel nadayag!\nA new event has been scheduled in your barangay:\nEvent: sample\nVenue: sample1\nStart: Oct 07, 2026 02:00 PM\nEnd: Oct 07, 2026 05:00 PM\nLead Facilitator: sample1\nDetails: sample1\nPlease be guided accordingly. Thank you!','sent','{\"data\":{\"success\":true,\"message\":\"SMS added to queue for processing\",\"smsBatchId\":\"6ac496972597187c9cc311a7\",\"recipientCount\":1}}','event_created',11,'2026-10-06 14:35:04');
